//! Relay wire protocol: protobuf messages generated by `prost`.
//!
//! Reliable channels exchange length-delimited messages
//! ([`encode_delimited`] / [`decode_delimited`]). Video slices do not use
//! protobuf; see `relay-net::video`.

#![allow(missing_debug_implementations)] // generated code

/// Current protocol version, sent in [`v1::Hello`].
pub const PROTOCOL_VERSION: u32 = 1;

/// Hard cap on a single reliable-stream message. Bigger messages are a
/// protocol violation (protects parsers from memory exhaustion).
pub const MAX_MESSAGE_LEN: usize = 4 * 1024 * 1024;

pub mod v1 {
    #![allow(clippy::all)]
    include!(concat!(env!("OUT_DIR"), "/relay.v1.rs"));
}

/// Rendezvous protocol (§8.3).
pub mod rdv {
    #![allow(clippy::all)]
    include!(concat!(env!("OUT_DIR"), "/relay.rdv.v1.rs"));
}

pub use prost::Message;

/// Error decoding a message from the wire.
#[derive(Debug)]
pub enum DecodeError {
    TooLarge(usize),
    Truncated,
    Prost(prost::DecodeError),
}

impl std::fmt::Display for DecodeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DecodeError::TooLarge(n) => write!(f, "message of {n} bytes exceeds limit"),
            DecodeError::Truncated => f.write_str("message truncated"),
            DecodeError::Prost(e) => write!(f, "{e}"),
        }
    }
}

impl std::error::Error for DecodeError {}

/// Encode `msg` with a varint length prefix.
pub fn encode_delimited<M: Message>(msg: &M) -> Vec<u8> {
    msg.encode_length_delimited_to_vec()
}

/// Decode one length-delimited message, enforcing [`MAX_MESSAGE_LEN`].
pub fn decode_delimited<M: Message + Default>(mut buf: &[u8]) -> Result<M, DecodeError> {
    let len = prost::decode_length_delimiter(&mut buf).map_err(DecodeError::Prost)?;
    if len > MAX_MESSAGE_LEN {
        return Err(DecodeError::TooLarge(len));
    }
    let body = buf.get(..len).ok_or(DecodeError::Truncated)?;
    M::decode(body).map_err(DecodeError::Prost)
}

#[cfg(test)]
mod tests {
    use super::v1::*;
    use super::*;

    #[test]
    fn control_round_trip() {
        let msg = ControlMessage {
            msg: Some(control_message::Msg::Hello(Hello {
                protocol_version: PROTOCOL_VERSION,
                device_pubkey: vec![7u8; 32].into(),
                device_id: 123_456_789,
                device_name: "office-pc".into(),
                os: OsKind::Windows as i32,
                capabilities: Some(Capabilities {
                    decoders: vec![Codec::H264 as i32],
                    ..Default::default()
                }),
                wake_macs: vec![vec![0, 0x11, 0x22, 0xaa, 0xbb, 0xcc].into()],
            })),
        };
        let wire = encode_delimited(&msg);
        let back: ControlMessage = decode_delimited(&wire).unwrap();
        assert_eq!(msg, back);
    }

    #[test]
    fn rejects_oversized_length_prefix() {
        let mut wire = Vec::new();
        prost::encode_length_delimiter(MAX_MESSAGE_LEN + 1, &mut wire).unwrap();
        let err = decode_delimited::<ControlMessage>(&wire).unwrap_err();
        assert!(matches!(err, DecodeError::TooLarge(_)));
    }

    #[test]
    fn rejects_truncated_message() {
        let msg = ChatMessage {
            id: 1,
            sent_at_ms: 2,
            text: "hello".into(),
        };
        let wire = encode_delimited(&msg);
        assert!(decode_delimited::<ChatMessage>(&wire[..wire.len() - 2]).is_err());
    }
}
